package io.github.diodeme.ji.spring;

import io.github.diodeme.ji.cli.LocalHostApplication;
import java.io.IOException;
import java.util.Map;

/** Framework-neutral factory exposed by the optional Spring Boot starter artifact. */
public final class JiHostFactory {
    public LocalHostApplication open(Map<String, String> configuration) throws IOException {
        return LocalHostApplication.open(configuration);
    }
}
